# orbits of A2 triangles of the unit under the subgroup of W(E8) generated by reflections / products of two reflections preserving the unit's line set
import sys,itertools
from a2lib import *
E=[tuple(Fr(x) for x in r) for r in E8]
def key(r):
    i=next(k for k in range(8) if r[k]!=0); s=1 if r[i]>0 else -1; return tuple(s*x for x in r)
idx={key(r):i for i,r in enumerate(E)}
Lk=[key(tuple(Fr(x) for x in r)) for r in L]; Lset=set(Lk); Lpos={k:i for i,k in enumerate(Lk)}
def refl(a):
    aa=sum(x*x for x in a)
    return lambda r: tuple(x-2*sum(p*q for p,q in zip(r,a))/aa*y for x,y in zip(r,a))
perms=[]
R1=[refl(a) for a in E]
for g in R1:
    img=[key(g(k)) for k in Lk]
    if set(img)==Lset: perms.append([Lpos[k] for k in img])
print('single reflections preserving L:',len(perms))
if len(perms)<200:
    for g,h in itertools.combinations(R1,2):
        img=[key(g(h(k))) for k in Lk]
        if set(img)==Lset: perms.append([Lpos[k] for k in img])
print('generators:',len(perms))
T=all_a2(); Tid={t:i for i,t in enumerate(T)}
par=list(range(len(T)))
def find(x):
    while par[x]!=x: par[x]=par[par[x]]; x=par[x]
    return x
for p in perms:
    for t in T:
        u=tuple(sorted(p[i] for i in t)); a,b=find(Tid[t]),find(Tid[u])
        if a!=b: par[a]=b
comps={}
for t in T: comps.setdefault(find(Tid[t]),[]).append(t)
print(UNIT,'triangles',len(T),'orbits(lower bound on merging)',len(comps),'reps',[c[0] for c in comps.values()],'sizes',sorted(len(c) for c in comps.values()))
